PRAGMA foreign_keys = ON;
CREATE TABLE libros (id INTEGER PRIMARY KEY AUTOINCREMENT, titulo TEXT NOT NULL, autor TEXT NOT NULL, anio_publicacion INTEGER NOT NULL);
CREATE TABLE socios (id INTEGER PRIMARY KEY AUTOINCREMENT, nombre TEXT NOT NULL, email TEXT NOT NULL UNIQUE, fecha_alta TEXT NOT NULL);
CREATE TABLE prestamos (id INTEGER PRIMARY KEY AUTOINCREMENT, id_libro INTEGER NOT NULL REFERENCES libros(id) ON DELETE RESTRICT, id_socio INTEGER NOT NULL REFERENCES socios(id) ON DELETE RESTRICT, fecha_prestamo TEXT NOT NULL, fecha_devolucion TEXT);
